LegoSet.query:
query ($id: ID) {
  LegoSet(id: $id) {
    name
    description
    year
    theme {
      name
      parent {
        name
      }
    }
  }
}

Minifig.query:
query ($id: ID) {
  Minifig(id: $id) {
    name
    figure_number
    num_parts
  }
}

Part.query:
query ($id: ID) {
  Part(id: $id) {
    name
    part_number
    category
    material
  }
}

Theme.query:
query ($id: ID) {
  Theme(id: $id) {
    name
    parent {
      name
    }
  }
}
